from collections import defaultdict

baseline = defaultdict(set)          # 에이전트 -> 평소에 하던 (행동, 대상)

def learn(events):
    for agent, action, target in events:
        baseline[agent].add((action, target))

def watch(events, rate_limit=20):
    alerts, count = [], defaultdict(int)
    for agent, action, target in events:
        count[agent] += 1
        if (action, target) not in baseline[agent]:
            alerts.append(f"처음 보는 행동: {agent} {action} {target}")
        if count[agent] == rate_limit + 1:
            alerts.append(f"속도 초과: {agent} 가 {rate_limit}회를 넘김")
    return alerts

learn([("mail-bot", "read", "inbox"), ("mail-bot", "send", "team@corp"),
       ("mail-bot", "send", "client@corp")])
